.globl evaluate_bayesian_trust
.type evaluate_bayesian_trust, @function
evaluate_bayesian_trust:
    mov rax, 0x3FF0000000000000
    movq xmm4, rax
    movsd xmm5, xmm4
    subsd xmm5, xmm0
    xor r9d, r9d
.Lbayes_loop:
    cmp r9d, edx
    jge .Lbayes_done
    movsxd rax, r9d
    movsd xmm1, qword ptr [rdi + rax*8]
    mulsd xmm0, xmm1
    movsd xmm2, qword ptr [rsi + rax*8]
    mulsd xmm5, xmm2
    inc r9d
    jmp .Lbayes_loop
.Lbayes_done:
    movsd xmm1, xmm0
    addsd xmm1, xmm5
    divsd xmm0, xmm1
    ret
.size evaluate_bayesian_trust, .-evaluate_bayesian_trust

.globl initialize_wave_field
.type initialize_wave_field, @function
initialize_wave_field:
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    sub rsp, 64
    mov rbx, rdi
    mov r12d, esi
    mov rax, 0x3FF0000000000000
    movq xmm4, rax
    subsd xmm4, xmm0
    mulsd xmm4, xmm1
    movq qword ptr [rsp], xmm4
    movsd xmm4, xmm2
    mulsd xmm4, xmm4
    mov rax, 0x4000000000000000
    movq xmm5, rax
    mulsd xmm4, xmm5
    mov rax, 0x3FF0000000000000
    movq xmm5, rax
    divsd xmm5, xmm4
    mov rax, 0x8000000000000000
    movq xmm4, rax
    xorpd xmm5, xmm4
    movq qword ptr [rsp + 8], xmm5
    movq qword ptr [rsp + 16], xmm3
    cmp r12d, 0
    jle .Lwave_done
    mov rdi, rbx
    movsd xmm0, qword ptr [rsp]
    movsd xmm1, qword ptr [rsp + 8]
    movsd xmm2, qword ptr [rsp + 16]
    call seed_cell_0000
    cmp r12d, 1
    jle .Lwave_done
    mov rdi, rbx
    movsd xmm0, qword ptr [rsp]
    movsd xmm1, qword ptr [rsp + 8]
    movsd xmm2, qword ptr [rsp + 16]
    call seed_cell_0001
    cmp r12d, 2
    jle .Lwave_done
    mov rdi, rbx
    movsd xmm0, qword ptr [rsp]
    movsd xmm1, qword ptr [rsp + 8]
    movsd xmm2, qword ptr [rsp + 16]
    call seed_cell_0002
    cmp r12d, 3
    jle .Lwave_done
    mov rdi, rbx
    movsd xmm0, qword ptr [rsp]
    movsd xmm1, qword ptr [rsp + 8]
    movsd xmm2, qword ptr [rsp + 16]
